// As definições reais, tal como estão em lib.es5.d.ts do TypeScript 5.9.3:
//   type Exclude<T, U> = T extends U ? never : T;
//   type Extract<T, U> = T extends U ? T : never;
//   type NonNullable<T> = T & {};

type Estado = "rascunho" | "revisao" | "publicado" | "arquivado";

type EstadoEditavel = Exclude<Estado, "publicado" | "arquivado">;
// "rascunho" | "revisao"

type EstadoFinal = Extract<Estado, "publicado" | "arquivado">;
// "publicado" | "arquivado"

type Titulo = NonNullable<string | null | undefined>;
// string

const emEdicao: EstadoEditavel = "revisao";
const fechado: EstadoFinal = "publicado";
const titulo: Titulo = "Relatorio anual";

// @ts-expect-error "publicado" foi retirado da união por Exclude
const invalido: EstadoEditavel = "publicado";

// No Módulo 06, o equivalente escrito à mão chamou-se TirarDaUniao. É a mesma linha.
type TirarDaUniao<T, U> = T extends U ? never : T;
type Igual = TirarDaUniao<Estado, "publicado" | "arquivado">;

const mesmoTipo: Igual = emEdicao;

console.log(emEdicao, fechado, titulo, mesmoTipo);
// revisao publicado Relatorio anual revisao

type Cor = "vermelho" | "verde" | "azul";

// Exclude<Cor, "verde"> distribui membro a membro:
//   ("vermelho" extends "verde" ? never : "vermelho")
// | ("verde"    extends "verde" ? never : "verde")
// | ("azul"     extends "verde" ? never : "azul")
// = "vermelho" | never | "azul" = "vermelho" | "azul"
type SemVerde = Exclude<Cor, "verde">;
const escolhida: SemVerde = "azul";

// Envolver os dois lados num tuplo desliga a distributividade: nada é retirado.
type NaoDistributivo<T, U> = [T] extends [U] ? never : T;
type Tentativa = NaoDistributivo<Cor, "verde">;
const aindaLa: Tentativa = "verde";

// A distributividade é o que torna Extract útil em uniões discriminadas.
type Evento =
  | { tipo: "clique"; x: number; y: number }
  | { tipo: "tecla"; codigo: string }
  | { tipo: "scroll"; delta: number };

type EventoTecla = Extract<Evento, { tipo: "tecla" }>;
type SemScroll = Exclude<Evento, { tipo: "scroll" }>;

const tecla: EventoTecla = { tipo: "tecla", codigo: "Enter" };

const qualquer: Evento = { tipo: "scroll", delta: 120 };
// @ts-expect-error a variável está tipada como Evento, que ainda inclui o scroll
const filtrado: SemScroll = qualquer;

// NonNullable já não é um conditional: é a interseção T & {}.
// O tipo {} aceita qualquer valor exceto null e undefined, logo a interseção elimina-os.
type Texto = NonNullable<string | null | undefined>;
const t: Texto = "presente";

// Por ser interseção e não conditional, aplica-se sem esperar pela resolução de T.
function primeiroDefinido<T>(valores: (T | null | undefined)[]): NonNullable<T> | undefined {
  for (const valor of valores) {
    if (valor !== null && valor !== undefined) {
      return valor;
    }
  }
  return undefined;
}

console.log(escolhida, aindaLa, tecla.codigo, t);
// azul verde Enter presente
console.log(primeiroDefinido([null, undefined, "encontrado"]));
// encontrado

interface Produto {
  id: number;
  nome: string;
  preco: number;
  stock: number;
  descricao: string;
}

// 1. Partial<Pick<T, K>>: estes campos, todos opcionais. O corpo de um PATCH.
type PatchProduto = Partial<Pick<Produto, "nome" | "preco" | "stock">>;
const patch: PatchProduto = { preco: 19.9 };

// 2. Omit<T, K> com interseção: substituir o tipo de um campo sem copiar a interface.
type ProdutoSerializado = Omit<Produto, "preco"> & { preco: string };
const enviado: ProdutoSerializado = {
  id: 1,
  nome: "Caneca",
  preco: "19.90",
  stock: 7,
  descricao: "Cerâmica pintada à mão",
};

// 3. Record<Exclude<keyof T, K>, V>: uma entrada por campo, menos as excluídas.
type Etiquetas = Record<Exclude<keyof Produto, "id">, string>;
const etiquetas: Etiquetas = {
  nome: "Nome",
  preco: "Preço",
  stock: "Em stock",
  descricao: "Descrição",
};

// 4. Readonly<Required<T>>: fechar os opcionais e congelar tudo de uma vez.
interface Configuracao {
  host?: string;
  porta?: number;
}
type ConfiguracaoResolvida = Readonly<Required<Configuracao>>;
const config: ConfiguracaoResolvida = { host: "localhost", porta: 8080 };

console.log(patch.preco, enviado.preco, etiquetas.preco, config.porta);
// 19.9 19.90 Preço 8080

// @ts-expect-error "id" foi retirado de Etiquetas por Exclude
etiquetas.id = "Identificador";

// @ts-expect-error Readonly tornou "porta" só de leitura
config.porta = 9090;

interface Definicoes {
  tema: { cor: string; contraste: number };
  etiquetas: string[];
  aoGuardar: (id: number) => void;
}

// A tentativa ingénua: um mapped type homomórfico que se chama a si próprio.
type Ingenuo<T> = { [K in keyof T]?: Ingenuo<T[K]> };

const ingenuo: Ingenuo<Definicoes> = { tema: { cor: "azul" }, etiquetas: ["nova"] };

// @ts-expect-error o "?" atravessou o array: cada elemento passou a string | undefined
const etiqueta: string = ingenuo.etiquetas![0];

const funcaoMapeada: Ingenuo<(id: number) => void> = (id: number) => console.log(id);

// @ts-expect-error a função foi mapeada como objeto e perdeu a assinatura de chamada
funcaoMapeada(1);
// 1 (o JavaScript emitido continua a ser uma função; perdeu-se apenas o tipo)

// A versão correta: parar nas funções, tratar os arrays à parte, só depois recorrer.
type ProfundamenteOpcional<T> =
  T extends (...args: never[]) => unknown ? T :
  T extends readonly (infer E)[] ? ProfundamenteOpcional<E>[] :
  T extends object ? { [K in keyof T]?: ProfundamenteOpcional<T[K]> } :
  T;

type ProfundamenteSoLeitura<T> =
  T extends (...args: never[]) => unknown ? T :
  T extends readonly (infer E)[] ? ReadonlyArray<ProfundamenteSoLeitura<E>> :
  T extends object ? { readonly [K in keyof T]: ProfundamenteSoLeitura<T[K]> } :
  T;

const bom: ProfundamenteOpcional<Definicoes> = {
  tema: { cor: "verde" },
  etiquetas: ["nova"],
  aoGuardar: (id) => console.log("guardado", id),
};

bom.aoGuardar?.(7);
// guardado 7
console.log(bom.etiquetas?.[0], bom.tema?.cor, bom.tema?.contraste);
// nova verde undefined

const congelado: ProfundamenteSoLeitura<Definicoes> = {
  tema: { cor: "azul", contraste: 4 },
  etiquetas: ["a"],
  aoGuardar: () => {},
};

// @ts-expect-error o readonly chegou à propriedade aninhada
congelado.tema.cor = "vermelho";

interface Utilizador {
  id: number;
  nome: string;
  email: string;
  ativo: boolean;
}

// Exige as chaves indicadas e torna o resto opcional.
type Atualizacao<T, K extends keyof T> = Pick<T, K> & Partial<Omit<T, K>>;

type AtualizarUtilizador = Atualizacao<Utilizador, "id">;

const pedido: AtualizarUtilizador = { id: 7, email: "ana@exemplo.pt" };

// @ts-expect-error falta o id, que Pick manteve obrigatório
const semId: AtualizarUtilizador = { email: "ana@exemplo.pt" };

// A constraint falha cedo, no sítio onde o engano foi escrito.
// @ts-expect-error "telefone" não satisfaz keyof Utilizador
type Impossivel = Atualizacao<Utilizador, "telefone">;

// Pelo menos uma: a união de "esta propriedade é obrigatória, as outras opcionais".
type PeloMenosUma<T, K extends keyof T = keyof T> =
  Partial<T> & { [C in K]-?: Required<Pick<T, C>> }[K];

type Filtro = PeloMenosUma<Pick<Utilizador, "nome" | "email">>;

const porNome: Filtro = { nome: "Ana" };
const porAmbos: Filtro = { nome: "Ana", email: "ana@exemplo.pt" };

// @ts-expect-error objeto vazio: nenhuma das propriedades foi dada
const vazio: Filtro = {};

function descrever(f: Filtro): string {
  return f.nome ?? f.email ?? "";
}

console.log(pedido.email, descrever(porNome), descrever(porAmbos));
// ana@exemplo.pt Ana Ana

interface PerfilPublico {
  nome: string;
  idade: number;
  subscrito: boolean;
}

type Campo<V> = {
  valor: V;
  erro: string | null;
  tocado: boolean;
};

// Cada campo do modelo passa a um Campo com o mesmo tipo de valor.
type Formulario<T> = { [K in keyof T]: Campo<T[K]> };

// Key remapping: um manipulador por campo, com o nome derivado da chave.
type Manipuladores<T> = {
  [K in keyof T as `mudar${Capitalize<string & K>}`]: (valor: T[K]) => void;
};

const form: Formulario<PerfilPublico> = {
  nome: { valor: "Ana", erro: null, tocado: true },
  idade: { valor: 34, erro: null, tocado: false },
  subscrito: { valor: false, erro: null, tocado: false },
};

// O caminho de volta: do formulário para o modelo de dados.
function valores<T>(f: Formulario<T>): T {
  const saida = {} as T;
  for (const chave in f) {
    saida[chave] = f[chave].valor;
  }
  return saida;
}

const acoes: Manipuladores<PerfilPublico> = {
  mudarNome: (valor) => console.log("nome:", valor),
  mudarIdade: (valor) => console.log("idade:", valor),
  mudarSubscrito: (valor) => console.log("subscrito:", valor),
};

acoes.mudarIdade(35);
// idade: 35
console.log(valores(form));
// { nome: 'Ana', idade: 34, subscrito: false }

// @ts-expect-error o campo "idade" continua a exigir number, tal como no modelo
form.idade.valor = "34";

interface Artigo {
  id: number;
  titulo: string;
  corpo: string;
}

// Sem constraint, um engano no nome da chave passa em silêncio.
type SemConstraint<T, K> = { [P in keyof T as P extends K ? never : P]: T[P] };
type AindaTudo = SemConstraint<Artigo, "titlo">;
const nadaFoiRetirado: AindaTudo = { id: 1, titulo: "Aberto", corpo: "Corpo" };

// Com constraint, o compilador aponta o dedo ao sítio onde o engano foi escrito.
type ComConstraint<T, K extends keyof T> = Omit<T, K>;
type SemTitulo = ComConstraint<Artigo, "titulo">;
const resumo: SemTitulo = { id: 1, corpo: "Corpo" };

// @ts-expect-error "titlo" não satisfaz keyof Artigo
type Erro = ComConstraint<Artigo, "titlo">;

// A recursão tem um teto real. Medido neste TypeScript 5.9.3:
// Repetir<999> compila e Repetir<1000> dá TS2589.
type Repetir<N extends number, Acc extends unknown[] = []> =
  Acc["length"] extends N ? Acc : Repetir<N, [...Acc, unknown]>;

type Tres = Repetir<3>;
const tres: Tres = [null, null, null];

console.log(nadaFoiRetirado.titulo, resumo.corpo, tres.length);
// Aberto Corpo 3

