type Metodo = "GET" | "HEAD" | "POST" | "PUT" | "DELETE";

type MetodoDeLeitura = Extract<Metodo, "GET" | "HEAD">;
type MetodoDeEscrita = Exclude<Metodo, "GET" | "HEAD">;

function ouEntao(valor: string | null | undefined, alternativa: string): NonNullable<string> {
  return valor ?? alternativa;
}

const leitura: MetodoDeLeitura = "HEAD";
const escrita: MetodoDeEscrita = "DELETE";

// @ts-expect-error "POST" não pertence aos métodos de leitura
const errado: MetodoDeLeitura = "POST";

console.log(leitura, escrita, ouEntao(null, "vazio"), ouEntao("dado", "vazio"));
// HEAD DELETE vazio dado

interface Encomenda {
  id: number;
  cliente: string;
  total: number;
  criadaEm: Date;
  notas: string;
}

type NovaEncomenda = Partial<Pick<Encomenda, "notas">> &
  Omit<Encomenda, "id" | "criadaEm" | "notas">;

type EncomendaEmJson = Omit<Encomenda, "criadaEm"> & { criadaEm: string };

const nova: NovaEncomenda = { cliente: "Ana", total: 42 };

const doServidor: EncomendaEmJson = {
  id: 1,
  cliente: "Ana",
  total: 42,
  criadaEm: "2024-03-01T10:00:00.000Z",
  notas: "",
};

// @ts-expect-error o id é atribuído pelo servidor: Omit retirou-o de NovaEncomenda
const comId: NovaEncomenda = { id: 9, cliente: "Ana", total: 42 };

console.log(nova.cliente, nova.notas, doServidor.criadaEm);
// Ana undefined 2024-03-01T10:00:00.000Z

type Substituir<T, K extends keyof T, V> = Omit<T, K> & Record<K, V>;

interface Registo {
  id: number;
  etiquetas: string[];
  atualizadoEm: Date;
}

type RegistoEmTexto = Substituir<Registo, "atualizadoEm", string>;

const emTexto: RegistoEmTexto = {
  id: 3,
  etiquetas: ["a", "b"],
  atualizadoEm: "2024-05-04",
};

// @ts-expect-error "criadoEm" não é chave de Registo: a constraint apanha o engano
type Impossivel = Substituir<Registo, "criadoEm", string>;

// @ts-expect-error depois da substituição "atualizadoEm" é string, não Date
const comData: RegistoEmTexto = { id: 3, etiquetas: [], atualizadoEm: new Date(0) };

console.log(emTexto.atualizadoEm, emTexto.etiquetas.length);
// 2024-05-04 2

type ExatamenteUma<T> = {
  [K in keyof T]: Required<Pick<T, K>> & Partial<Record<Exclude<keyof T, K>, never>>;
}[keyof T];

interface Identificacao {
  id: number;
  email: string;
  telefone: string;
}

type ChaveDeBusca = ExatamenteUma<Identificacao>;

const porId: ChaveDeBusca = { id: 10 };
const porEmail: ChaveDeBusca = { email: "ana@exemplo.pt" };

// @ts-expect-error duas chaves ao mesmo tempo: as restantes foram fixadas em never
const duas: ChaveDeBusca = { id: 10, email: "ana@exemplo.pt" };

// @ts-expect-error nenhuma chave: a união exige sempre uma
const nenhuma: ChaveDeBusca = {};

function descrever(chave: ChaveDeBusca): string {
  if (chave.id !== undefined) return `id=${chave.id}`;
  if (chave.email !== undefined) return `email=${chave.email}`;
  return `telefone=${chave.telefone}`;
}

console.log(descrever(porId), descrever(porEmail));
// id=10 email=ana@exemplo.pt
